import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config({"BLOCK_SIZE": 1024}, num_warps=4, num_stages=2),
        triton.Config({"BLOCK_SIZE": 2048}, num_warps=4, num_stages=2),
        triton.Config({"BLOCK_SIZE": 4096}, num_warps=8, num_stages=2),
        triton.Config({"BLOCK_SIZE": 8192}, num_warps=8, num_stages=2),
        triton.Config({"BLOCK_SIZE": 8192}, num_warps=16, num_stages=2),
    ],
    key=["n_elements"],
)
@triton.jit
def elu_kernel(
    x_ptr,
    out_ptr,
    alpha,
    n_elements,
    BLOCK_SIZE: tl.constexpr,
):
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements

    x = tl.load(x_ptr + offsets, mask=mask, other=0.0)
    x_f32 = x.to(tl.float32)

    inv_ln2: tl.constexpr = 1.4426950408889634
    exp_x = tl.math.exp2(x_f32 * inv_ln2)
    neg_branch = alpha * (exp_x - 1.0)

    result = tl.where(x_f32 > 0.0, x_f32, neg_branch)

    tl.store(out_ptr + offsets, result.to(x.dtype), mask=mask)


class Model(nn.Module):
    def __init__(self, alpha=1.0):
        super(Model, self).__init__()
        try:
            self.alpha = float(alpha)
        except (ValueError, TypeError):
            self.alpha = 1.0

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        out = torch.empty_like(x)
        n_elements = x.numel()
        grid = lambda META: (triton.cdiv(n_elements, META["BLOCK_SIZE"]),)
        elu_kernel[grid](x, out, self.alpha, n_elements)
        return out
